const HERO_ICONS = { lia_hero: 'crown', lilith_hero: 'crown', serena_hero: 'crown', n_dragon: 'dragon', n_angel: 'angel' };
const CLASS_ICON = { lia: 'guard', lilith: 'dagger', serena: 'moon-orb', neutral: 'sword' };
